<template>
  <section class="review"><h3>Revisión</h3><p v-if="locked" class="notice">La generación de retratos está en curso. La revisión estará disponible al terminar.</p><p v-if="loading">Cargando revisión...</p><p v-else-if="loadError" class="error">{{ loadError }} <button type="button" class="link" @click="load">Reintentar</button></p><template v-else><div v-if="review" class="proposal"><p><strong>Propuesta pendiente</strong></p><p v-if="review.target !== 'VISUAL'"><strong>Descripción narrativa</strong><br>{{ review.narrativeDescription }}</p><p v-if="review.target !== 'NARRATIVE'"><strong>Descripción visual</strong><br>{{ review.visualDescription }}</p><p v-if="visualWarning" class="notice">Este cambio puede afectar a la consistencia visual existente.</p><button type="button" class="btn" :disabled="locked || resolving" @click="resolve('CONFIRMED')">Aceptar</button><button type="button" class="btn" :disabled="locked || resolving" @click="resolve('DISCARDED')">Descartar</button></div><form class="request" @submit.prevent="request(false)"><label>Campo<select v-model="target" :disabled="locked || submitting || resolving"><option value="NARRATIVE">Narrativa</option><option value="VISUAL">Visual</option><option value="BOTH">Ambos</option></select></label><label for="review-hint">Cambio solicitado<textarea id="review-hint" v-model.trim="hint" required :disabled="locked || submitting || resolving" /></label><p v-if="rejection" class="error">{{ rejection }}</p><p v-if="requestError" class="error">{{ requestError }}</p><button type="submit" class="btn" :disabled="locked || submitting || resolving || !hint">{{ submitting ? 'Enviando...' : 'Solicitar revisión' }}</button></form></template><confirm-modal :open="confirmReplace" title="Sustituir revisión pendiente" message="Ya hay una revisión pendiente. Se descartará antes de crear la nueva." confirm-label="Sustituir" @confirm="request(true)" @cancel="confirmReplace = false" /><confirm-modal :open="confirmFork" title="Crear personaje derivado" message="El personaje ya se usa en cuentos. Se creará un personaje derivado con el cambio visual; el original seguirá intacto." confirm-label="Crear derivado" @confirm="confirmForkCreation" @cancel="confirmFork = false" /></section>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import { getPendingCatalogCharacterReview, requestCatalogCharacterReview, resolveCatalogCharacterReview, type CatalogCharacterReview, type CharacterReviewResolution, type CharacterReviewTarget } from '../api/characters'
import { ApiError } from '../api/httpClient'
import ConfirmModal from './ConfirmModal.vue'
const props = defineProps<{ characterId: number; locked?: boolean }>(); const emit = defineEmits<{ changed: [forkCatalogCharacterId?: number] }>()
const review = ref<CatalogCharacterReview | null>(null); const loading = ref(false); const loadError = ref<string | null>(null); const target = ref<CharacterReviewTarget>('NARRATIVE'); const hint = ref(''); const submitting = ref(false); const resolving = ref(false); const rejection = ref<string | null>(null); const requestError = ref<string | null>(null); const confirmReplace = ref(false); const confirmFork = ref(false); const visualWarning = ref(false)
const error = (value: unknown, fallback: string) => value instanceof ApiError ? value.message : fallback
async function load() { loading.value = true; loadError.value = null; try { review.value = await getPendingCatalogCharacterReview(props.characterId) } catch (value) { if (value instanceof ApiError && value.status === 404) review.value = null; else loadError.value = error(value, 'No se pudo cargar la revisión') } finally { loading.value = false } }
async function request(replacePending: boolean) { if (props.locked || !hint.value || submitting.value) return; confirmReplace.value = false; submitting.value = true; rejection.value = null; requestError.value = null; visualWarning.value = false; try { const result = await requestCatalogCharacterReview(props.characterId, target.value, hint.value, replacePending); if (result.replacementConfirmationRequired) { confirmReplace.value = true; return }; if (!result.proposal?.accepted) { rejection.value = result.proposal?.rejectionReason || 'El cambio fue rechazado.'; return }; visualWarning.value = result.visualConsistencyWarning; await load(); emit('changed') } catch (value) { requestError.value = error(value, 'No se pudo solicitar la revisión') } finally { submitting.value = false } }
async function resolve(status: CharacterReviewResolution, confirmForkValue = false) { if (props.locked || !review.value || resolving.value) return; resolving.value = true; requestError.value = null; try { const result = await resolveCatalogCharacterReview(props.characterId, review.value.id, status, confirmForkValue); if (status === 'CONFIRMED' && result.forkConfirmationRequired && !confirmForkValue) { confirmFork.value = true; return }; review.value = null; confirmFork.value = false; emit('changed', result.forkCatalogCharacterId ?? undefined) } catch (value) { requestError.value = error(value, 'No se pudo resolver la revisión') } finally { resolving.value = false } }
async function confirmForkCreation() { await resolve('CONFIRMED', true) }
watch(() => props.locked, (locked) => { if (locked) confirmFork.value = false })
watch(() => props.characterId, () => { review.value = null; hint.value = ''; rejection.value = null; requestError.value = null; visualWarning.value = false; confirmFork.value = false; load() }, { immediate: true })
</script>
<style scoped>.review{display:grid;gap:12px;margin-top:20px;padding-top:16px;border-top:1px solid var(--border)}h3,p{margin:0}.request{display:grid;gap:8px}.request label{display:grid;gap:4px;font-size:14px;font-weight:600;color:var(--text-h)}textarea,select{padding:8px;font:inherit;color:var(--text-h);background:var(--bg);border:1px solid var(--border);border-radius:6px}.btn{margin-right:8px;padding:8px 16px;font:inherit;cursor:pointer;color:var(--text-h);background:transparent;border:1px solid var(--border);border-radius:6px}.btn:disabled{opacity:.5;cursor:not-allowed}.error{color:#e5484d}.notice{color:#92400e}.link{padding:0;color:inherit;background:transparent;border:0;text-decoration:underline;cursor:pointer}</style>
